public static byte[] getBytes(final BigInteger value) {
    final byte[] result = new byte[8];
    BigInteger remaining = value;
    for (int i = result.length - 1; i >= 0; i--) {
        result[i] = remaining.byteValue();
        remaining = remaining.shiftRight(8);
    }
    return result;
}
